Given an n*m matrix where all numbers are distinct, the task is to find the maximum length path (starting from any cell) such that all cells along the path are in increasing order with a difference of 1. We can move in 4 directions from a given cell (i, j), i.e., we can move to (i+1, j) or (i, j+1) or (i-1, j) or (i, j-1) with the condition that the adjacent cells have a difference of 1.Example: Input:n = 3, m = 3matrix[][] = [[1 2 9],                     [5 3 8],                    [4 6 7]]Output: 4Explanation:  The longest increasing path is  [6, 7, 8, 9]. Input: n = 3, m = 3matrix[][] = [[3 4 5],                     [6 7 8],                     [10 2 1]]Output: 3Explanation: The longest increasing path is [3, 4, 5].Try It YourselfTable of ContentUsing Depth First Search - O((n*m)^(n*m)) Time and O(n*m) SpaceUsing DFS and Memoization - O(n*m) Time and O(n*m) SpaceUsing Depth First Search - O((n*m)^(n*m)) Time and O(n*m) SpaceThe idea is to perform a depth-first search (DFS) from every cell in the matrix, exploring all possible paths that satisfy the strictly increasing condition. For each cell, we will recursively try moving in all four directions (up, down, left, right), keeping track of the current path length and ensuring that the next cell has a strictly higher value than the current cell. 
            C++

    // C++ program to find the longest path
// in a matrix with given constraints
#include <bits/stdc++.h>
using namespace std;

int longestPath(int i, int j, vector<vector<int>> &matrix) {
    int ans = 1;

    vector<vector<int>> dir = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Check for all 4 directions
    for (auto d : dir) {
        int x = i + d[0];
        int y = j + d[1];

        // If new cells are valid and
        // increasing by 1.
        if (x >= 0 && x < matrix.size() && y >= 0 && 
            y < matrix[0].size() && matrix[x][y] == matrix[i][j] + 1) {
            ans = max(ans, 1 + longestPath(x, y, matrix));
        }
    }

    return ans;
}

int longestIncreasingPath(vector<vector<int>> &matrix) {
    int ans = 0;

    // Find length of longest path
    // from each cell i, j
    for (int i = 0; i < matrix.size(); i++) {
        for (int j = 0; j < matrix[0].size(); j++) {
            int val = longestPath(i, j, matrix);
            ans = max(ans, val);
        }
    }

    return ans;
}

int main() {
    vector<vector<int>> matrix = {{1, 2, 9}, {5, 3, 8}, {4, 6, 7}};
    cout << longestIncreasingPath(matrix);

    return 0;
}


